mapper.select:
SELECT scu.*
FROM eb_store_coupon_user scu
INNER JOIN eb_store_coupon sc ON scu.coupon_id = sc.id
WHERE
scu.`status` = 0
AND sc.coupon_type = 1
AND scu.min_price <= #{maxPrice}
AND scu.start_time < #{date} AND scu.end_time > #{date}
AND scu.uid = #{uid}
AND (scu.use_type = 1
         or (scu.use_type = 2 and

    find_in_set(#{proId}, scu.primary_key)

         )
         or (scu.use_type = 3 and

    find_in_set(#{cateId}, scu.primary_key)

         )
    )
order by scu.id desc
